TEE_Result populate_crypto_object(unsigned long obj, struct utee_attribute *usr_attrs,
                                  unsigned long attr_count) {
    TEE_Result res = TEE_SUCCESS;
    struct tee_session *session;
    struct tee_obj *object;
    struct tee_attribute *attrs = NULL;

    session = tee_get_current_session();
    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    object = tee_get_object_by_id(session, obj);
    if (!object || !object->is_transient || object->is_initialized) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    attrs = calloc(attr_count, sizeof(struct tee_attribute));
    if (!attrs) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    for (unsigned long i = 0; i < attr_count; ++i) {
        attrs[i] = usr_attrs[i];
    }

    res = validate_attributes_against_type(object->type, attrs, attr_count);
    if (res != TEE_SUCCESS) {
        goto cleanup;
    }

    res = tee_populate_object(object, attrs, attr_count);
    if (res != TEE_SUCCESS) {
        goto cleanup;
    }

    object->is_initialized = 1;

cleanup:
    free(attrs);
    return res;
}

TEE_Result populate_crypto_object(unsigned long obj,
                                  struct utee_attribute *usr_attrs,
                                  unsigned long attr_count)
{
    TEE_Result res = TEE_SUCCESS;
    struct crypto_session *session = get_current_session();
    struct crypto_object *cobj = NULL;

    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    cobj = get_object_by_id(session, obj);
    if (!cobj || !is_transient(cobj) || is_initialized(cobj)) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    cobj->attributes = calloc(attr_count, sizeof(struct utee_attribute));
    if (!cobj->attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    if (copy_from_user(cobj->attributes, (void *)usr_attrs,
                       attr_count * sizeof(struct utee_attribute)) != 0) {
        res = TEE_ERROR_BAD_PARAMETERS;
        goto error_cleanup;
    }

    if (validate_attributes(cobj, cobj->attributes, attr_count) != TEE_SUCCESS) {
        res = TEE_ERROR_BAD_PARAMETERS;
        goto error_cleanup;
    }

    cobj->is_initialized = 1;
    return TEE_SUCCESS;

error_cleanup:
    free(cobj->attributes);
    cobj->attributes = NULL;
    return res;
}

TEE_Result populate_crypto_object(unsigned long obj, struct utee_attribute *usr_attrs, unsigned long attr_count) {
    TEE_Result res = TEE_ERROR_GENERIC;
    void *attrs = NULL;
    struct tee_session *session = NULL;

    session = get_current_session();
    if (!session)
        return TEE_ERROR_BAD_STATE;

    if (!is_transient_uninitialized(obj))
        return TEE_ERROR_BAD_STATE;

    attrs = malloc(attr_count * sizeof(struct utee_attribute));
    if (!attrs)
        return TEE_ERROR_OUT_OF_MEMORY;

    if (copy_from_user(attrs, usr_attrs, attr_count * sizeof(struct utee_attribute))) {
        free(attrs);
        return TEE_ERROR_BAD_PARAMETERS;
    }

    res = validate_attributes(obj, attrs, attr_count);
    if (res != TEE_SUCCESS) {
        free(attrs);
        return res;
    }

    res = initialize_object(obj, attrs, attr_count);
    if (res != TEE_SUCCESS) {
        free(attrs);
        return res;
    }

    mark_object_initialized(obj);
    free(attrs);
    return TEE_SUCCESS;
}

TEE_Result populate_crypto_object(unsigned long obj, struct utee_attribute *usr_attrs, unsigned long attr_count) {
    TEE_Result res = TEE_SUCCESS;
    struct tee_session *session = tee_get_current_session();

    if (!session || !usr_attrs || attr_count == 0)
        return TEE_ERROR_BAD_PARAMETERS;

    struct crypto_object *target_obj = get_crypto_object_by_id(obj);
    if (!target_obj || !target_obj->is_transient || target_obj->is_initialized)
        return TEE_ERROR_BAD_STATE;

    struct tee_attribute *attrs = NULL;
    attrs = calloc(attr_count, sizeof(struct tee_attribute));
    if (!attrs) {
        res = TEE_ERROR_OUT_OF_MEMORY;
        goto cleanup;
    }

    for (unsigned long i = 0; i < attr_count; ++i) {
        attrs[i] = usr_attrs[i]; // Copy attributes from user space
    }

    res = validate_attributes(attrs, attr_count, target_obj->type);
    if (res != TEE_SUCCESS)
        goto cleanup;

    res = set_crypto_attributes(target_obj, attrs, attr_count);
    if (res != TEE_SUCCESS)
        goto cleanup;

    target_obj->is_initialized = 1;

cleanup:
    if (attrs)
        free(attrs);

    return res;
}

TEE_Result populate_crypto_object(unsigned long obj, struct utee_attribute *usr_attrs, unsigned long attr_count) {
    TEE_Result res = TEE_SUCCESS;
    struct tee_session *session = TEE_GetCurrentSession();
    struct tee_object *target_obj = NULL;
    struct tee_attribute *allocated_attrs = NULL;

    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    target_obj = get_object_by_id(obj);
    if (!target_obj || !is_transient_object(target_obj) || is_initialized(target_obj)) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    allocated_attrs = malloc(sizeof(struct tee_attribute) * attr_count);
    if (!allocated_attrs) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    for (unsigned long i = 0; i < attr_count; ++i) {
        const struct utee_attribute *usr_attr = &usr_attrs[i];

        if (!usr_attr || !validate_user_attribute(usr_attr)) {
            res = TEE_ERROR_BAD_PARAMETERS;
            break;
        }

        struct tee_attribute *kattr = &allocated_attrs[i];
        *kattr = convert_user_to_kernel_attribute(usr_attr);

        if (!validate_attribute_for_object_type(kattr, target_obj)) {
            res = TEE_ERROR_NOT_SUPPORTED;
            break;
        }
    }

    if (res == TEE_SUCCESS) {
        if (!populate_object_with_attributes(target_obj, allocated_attrs, attr_count)) {
            res = TEE_ERROR_GENERIC;
        } else {
            mark_object_as_initialized(target_obj);
        }
    }

    free(allocated_attrs);
    return res;
}
